export const clone=x=>structuredClone(x);
export const height=n=>n?1+Math.max(height(n.left),height(n.right)):-1;
const size=n=>n?1+size(n.left)+size(n.right):0;
const node=v=>({v,left:null,right:null});
const sorted=a=>[...a].sort((x,y)=>x-y);
function assert(ok,msg){if(!ok)throw Error(msg)}
export function ints(raw,max=24){const a=raw.trim().split(/[,，\s]+/).map(Number);assert(a.length&&a.length<=max&&a.every(x=>Number.isSafeInteger(x)&&Math.abs(x)<=999),`请输入 1–${max} 个 −999 到 999 的整数。`);return a}
function positive(raw,max=16){const a=ints(raw,max);assert(a.every(x=>x>0),'请输入正整数。');return a}
function ops(raw){const tokens=raw.split(/[,，\s]+/);assert(tokens.length<=30,'每次最多 30 个操作。');return tokens.map(t=>{const m=/^(?:(i|d|f):)?(-?\d+)$/.exec(t);assert(m&&Math.abs(+m[2])<=999,'操作格式：30,20,d:20,f:30；键为 −999 到 999 的整数。');return{type:m[1]||'i',v:+m[2]}})}
function decorate(n,mode){if(!n)return n;decorate(n.left,mode);decorate(n.right,mode);if(mode==='avl')n.meta=`h=${height(n)} · BF=${height(n.left)-height(n.right)}`;if(mode==='splay')n.meta=`s=${size(n)}`;return n}
function treeFrame(root,msg,hot=[],mode='avl',metrics={}){return{kind:'tree',roots:root?[decorate(clone(root),mode)]:[],hot,msg,metrics:{'节点数':size(root),'高度（空树 −1）':height(root),...metrics}}}
function rotate(t,dir){if(dir==='left'){const p=t.right;t.right=p.left;p.left=t;return p}const p=t.left;t.left=p.right;p.right=t;return p}
export function avlTrace(operations){const box={root:null},f=[];const snap=(msg,hot=[])=>f.push(treeFrame(box.root,msg,hot));function balance(p,key){const t=p[key];if(!t)return;const bf=height(t.left)-height(t.right);if(bf>1){snap(`节点 ${t.v} 失衡：BF=${bf}，检查左孩子。`,[t.v]);if(height(t.left.left)<height(t.left.right)){t.left=rotate(t.left,'left');snap('LR 型：先对失衡点左孩子左旋。',[t.left.v,t.v])}p[key]=rotate(t,'right');snap(`右旋 ${t.v}，子树根变为 ${p[key].v}。`,[p[key].v,t.v])}else if(bf< -1){snap(`节点 ${t.v} 失衡：BF=${bf}，检查右孩子。`,[t.v]);if(height(t.right.right)<height(t.right.left)){t.right=rotate(t.right,'right');snap('RL 型：先对失衡点右孩子右旋。',[t.right.v,t.v])}p[key]=rotate(t,'left');snap(`左旋 ${t.v}，子树根变为 ${p[key].v}。`,[p[key].v,t.v])}}function insert(p,key,v){const t=p[key];if(!t){p[key]=node(v);snap(`按 BST 次序插入叶子 ${v}。`,[v]);return}snap(`比较 ${v} 与 ${t.v}。`,[t.v]);if(v===t.v){snap(`键 ${v} 已存在，集合不重复插入。`,[v]);return}insert(t,v<t.v?'left':'right',v);balance(p,key)}function del(p,key,v){let t=p[key];if(!t)return false;if(v<t.v){const found=del(t,'left',v);balance(p,key);return found}if(v>t.v){const found=del(t,'right',v);balance(p,key);return found}if(!t.left||!t.right){p[key]=t.left||t.right;snap(`移除 ${v}，把其唯一孩子或空树接回。`)}else{let s=t.right;while(s.left)s=s.left;snap(`双孩子删除：选择中序后继 ${s.v} 替代 ${v}。`,[v,s.v]);const sv=s.v;del(t,'right',sv);t.v=sv;snap(`完成后继替换，更新祖先高度。`,[sv])}balance(p,key);return true}snap('空 AVL 树。每次更新后验证整个树的平衡性。');for(const {type,v}of operations){if(type==='i')insert(box,'root',v);else if(type==='d'){if(!del(box,'root',v))snap(`键 ${v} 不存在，删除不改变树。`)}else{let t=box.root;while(t){snap(`查找 ${v}：检查 ${t.v}。`,[t.v]);if(t.v===v)break;t=v<t.v?t.left:t.right}snap(t?`找到键 ${v}。`:`未找到键 ${v}。`,t?[v]:[])}snap(`${type==='i'?'插入':type==='d'?'删除':'查找'} ${v} 完成。`,[v])}return f}
function pathTo(root,v){let p=[];while(root){p.push(root);if(root.v===v)break;root=v<root.v?root.left:root.right}return p}
export function splayTrace(operations){const box={root:null},f=[];const snap=(msg,hot=[])=>f.push(treeFrame(box.root,msg,hot,'splay'));function turn(target,dir,msg){const path=pathTo(box.root,target.v),parent=path.at(-2);const out=rotate(target,dir);if(parent)parent[parent.left===target?'left':'right']=out;else box.root=out;snap(msg,[target.v,out.v])}function splay(v){while(box.root?.v!==v){const pth=pathTo(box.root,v),x=pth.at(-1),p=pth.at(-2),g=pth.at(-3);if(!p||x.v!==v)return;if(!g){turn(p,x===p.left?'right':'left','Zig：目标的父亲是根，执行一次旋转。')}else if((g.left===p)===(p.left===x)){const dir=g.left===p?'right':'left';turn(g,dir,'Zig-zig 第一步：先旋转祖父。');turn(p,dir,'Zig-zig 第二步：再把目标旋转上去。')}else{turn(p,p.left===x?'right':'left','Zig-zag 第一步：目标与父亲旋转。');turn(g,g.left===x?'right':'left','Zig-zag 第二步：目标与祖父旋转。')}}}snap('空 Splay 树，访问后把目标伸展到根。');for(const {type,v}of operations){let path=pathTo(box.root,v),last=path.at(-1);if(type==='i'&&last?.v!==v){const n=node(v);if(!last)box.root=n;else last[v<last.v?'left':'right']=n;snap(`BST 插入 ${v}，接下来伸展。`,[v]);splay(v)}else if(last){snap(`${type==='d'?'删除':'访问'} ${v}：${last.v===v?'找到目标':'未找到，伸展最后访问节点 '+last.v}。`,[last.v]);splay(last.v);if(type==='d'&&box.root.v===v){const right=box.root.right;box.root=box.root.left;snap(`移除根 ${v}，暂存右子树，处理左子树。`);if(!box.root)box.root=right;else{let m=box.root;while(m.right)m=m.right;splay(m.v);box.root.right=right}snap('左子树最大值成为根，接回暂存的右子树。')}}snap(`操作完成，当前根为 ${box.root?.v??'空'}。`,box.root?[box.root.v]:[])}return f}
export function rbTrace(operations){const box={root:null},f=[];const snap=(msg,hot=[])=>f.push(treeFrame(box.root,msg,hot,'rb'));const red=n=>n?.color==='red';function turn(t,dir){const p=pathTo(box.root,t.v).at(-2),out=rotate(t,dir);if(p)p[p.left===t?'left':'right']=out;else box.root=out;snap(`对 ${t.v} ${dir==='left'?'左':'右'}旋。`,[t.v,out.v])}snap('空红黑树，所有隐式 NIL 均为黑。');for(const {type,v}of operations){assert(type!=='d','红黑树实验支持插入和 f:查找；删除修复见本章讲义。');const path=pathTo(box.root,v),parent=path.at(-1);if(type==='f'||parent?.v===v){path.forEach(t=>snap(`比较目标 ${v} 与 ${t.v}。`,[t.v]));snap(parent?.v===v?`键 ${v} 已存在。`:`未找到 ${v}。`);continue}let z={...node(v),color:'red'};if(!parent)box.root=z;else parent[v<parent.v?'left':'right']=z;snap(`插入红节点 ${v}，检查红红冲突。`,[v]);while(true){const path=pathTo(box.root,z.v),p=path.at(-2),g=path.at(-3);if(!red(p)||!g)break;const left=g.left===p,u=left?g.right:g.left;if(red(u)){p.color=u.color='black';g.color='red';snap('父亲与叔叔为红：父叔染黑，祖父染红，向上继续。',[p.v,u.v,g.v]);z=g}else{if((left&&p.right===z)||(!left&&p.left===z)){turn(p,left?'left':'right');z=p}const path2=pathTo(box.root,z.v),p2=path2.at(-2),g2=path2.at(-3);p2.color='black';g2.color='red';snap('叔叔为黑：将直线结构的父亲染黑、祖父染红。',[p2.v,g2.v]);turn(g2,left?'right':'left');break}}box.root.color='black';snap(`插入 ${v} 完成，根染黑。`,[v])}return f}
export function bplusTrace(operations){let uid=0;const leaf=()=>({id:uid++,leaf:true,keys:[]});let root=leaf(),frames=[];function minimum(t){while(!t.leaf)t=t.children[0];return t.keys[0]}function refresh(t){if(!t.leaf)t.keys=t.children.slice(1).map(minimum)}function snap(msg,hot=[]){const levels=[];function walk(t,d){(levels[d]??=[]).push({id:t.id,keys:[...t.keys],leaf:t.leaf,children:t.children?.map(c=>c.id)||[]});t.children?.forEach(c=>walk(c,d+1))}walk(root,0);frames.push({kind:'bplus',levels,hot,msg,metrics:{'最大扇出 M':4,'叶深':levels.length-1}})}function put(t,v){if(t.leaf){if(t.keys.includes(v))return null;t.keys=sorted([...t.keys,v]);snap(`数据键 ${v} 加入叶页，最多容纳 4 个键。`,[t.id]);if(t.keys.length>4){const right=leaf();right.keys=t.keys.splice(3);return right}return null}let i=0;while(i<t.keys.length&&v>=t.keys[i])i++;snap(`在内部页比较分隔键，进入第 ${i+1} 个孩子。`,[t.id]);const newRight=put(t.children[i],v);if(newRight){t.children.splice(i+1,0,newRight);refresh(t);snap('子页分裂：插入新的右侧孩子并更新分隔键。',[t.id])}refresh(t);if(t.children.length>4){const right={id:uid++,leaf:false,children:t.children.splice(3),keys:[]};refresh(t);refresh(right);return right}return null}snap('空 B+ 树，内部最多 4 个孩子，叶子最多 4 个数据键。');for(const{type,v}of operations){assert(type!=='d','B+ 实验支持插入和 f:查找，范围导航可从叶链观察。');if(type==='f'){let t=root;while(!t.leaf){snap(`查找 ${v}：等于分隔键时向右。`,[t.id]);let i=0;while(i<t.keys.length&&v>=t.keys[i])i++;t=t.children[i]}snap(t.keys.includes(v)?`在叶页找到 ${v}。`:`叶页中没有 ${v}。`,[t.id]);continue}const right=put(root,v);if(right){root={id:uid++,leaf:false,children:[root,right],keys:[]};refresh(root);snap('根分裂，建立新的内部根。',[root.id])}snap(`插入 ${v} 完成，所有叶页仍同深。`)}return frames}
export function stackTrace(raw){const tokens=raw.split(/[,，\s]+/),stack=[],frames=[];assert(tokens.length<=40,'每次最多 40 个栈操作。');let actual=0,amortized=0;frames.push({kind:'array',array:[],msg:'空栈，势能 Φ=0。',metrics:{'累计元素处理成本':0,'累计摊还成本':0}});for(const t of tokens){const m=/^(push:-?\d+|pop|multi:\d+)$/.exec(t);assert(m,'格式：push:3,push:5,pop,multi:2。');let c=0,delta=0;if(t.startsWith('push:')){const v=+t.slice(5);assert(Math.abs(v)<=999,'栈元素需在 −999 到 999。');stack.push(v);c=1;delta=1}else{const k=t==='pop'?1:+t.slice(6),count=Math.min(k,stack.length);stack.splice(stack.length-count,count);c=count;delta=-count}actual+=c;amortized+=c+delta;frames.push({kind:'array',array:[...stack],hot:stack.length?[stack.length-1]:[],msg:`${t}：实际元素成本 ${c}，ΔΦ=${delta}，摊还成本 ${c+delta}。右端为栈顶。`,metrics:{'势能 Φ':stack.length,'累计实际元素成本':actual,'累计摊还元素成本':amortized}})}return frames}
function twoArrays(raw){const parts=raw.split(/[;；]/);assert(parts.length===2,'两组整数请用分号分隔。');return parts.map(s=>s.trim()?ints(s,16):[])}
export function heapTrace(pair,skew=false){let frames=[],steps=0;const npl=n=>n?n.npl:-1;const f=(roots,msg,hot=[])=>frames.push({kind:'tree',roots:clone(roots.filter(Boolean)),msg,hot,metrics:{'本次合并递归比较':steps,'结构':skew?'斜堆 · 无 npl':'左式堆 · 标注 npl'}});function merge(a,b,show=true){if(!a)return b;if(!b)return a;if(show){steps++;f([a,b],`局部 merge：比较两根 ${a.v} 与 ${b.v}。`,[a.v,b.v])}if(a.v>b.v)[a,b]=[b,a];a.right=merge(a.right,b,show);if(skew||npl(a.left)<npl(a.right)){[a.left,a.right]=[a.right,a.left];if(show)f([a],skew?'回溯：无条件交换左右孩子。':'回溯：左侧 npl 较小，交换孩子。',[a.v])}if(!skew){a.npl=npl(a.right)+1;a.meta=`npl=${a.npl}`}return a}function build(a){let h=null;for(const v of a)h=merge(h,{...node(v),npl:0,meta:skew?undefined:'npl=0'},false);return h}const a=build(pair[0]),b=build(pair[1]);f([a,b],'H₁ 与 H₂ 分别由输入构建。下一步开始展示局部递归合并。');let h=merge(a,b);f([h],'两堆合并完成：这里展示完整结果。');if(h){const v=h.v;steps=0;h=merge(h.left,h.right);f([h],`deleteMin 删除 ${v} 后，合并其两棵孩子，完整结果如图。`)}return frames}
export function binomialTrace(values){let forest=[],frames=[],links=0;const snap=(msg,extra=[])=>frames.push({kind:'tree',roots:clone([...forest.filter(Boolean),...extra]),msg,metrics:{'根的阶数':forest.map((x,i)=>x?i:null).filter(x=>x!==null).join(', ')||'∅','累计链接次数':links}});function link(a,b){if(a.v>b.v)[a,b]=[b,a];a.children.unshift(b);a.order++;a.meta=`B${a.order}`;links++;return a}function add(t){while(forest[t.order]){const k=t.order,a=forest[k];forest[k]=null;t=link(a,t);snap(`两个 B${k} 链接，产生进位 B${k+1}。`,[t])}forest[t.order]=t}snap('空二项森林，按阶存储树。');for(const v of values){const t={v,children:[],order:0,meta:'B0'};snap(`插入单节点 ${v}，从 B0 开始进位。`,[t]);add(t);snap(`插入 ${v} 完成，当前森林大小对应二进制位。`)}return frames}
export function invertedTrace(pair){assert(pair.every(a=>a.every((x,i)=>x>=0&&(!i||x>a[i-1]))),'倒排表必须是非负、严格递增的文档编号。');const[a,b]=pair,frames=[],out=[];let i=0,j=0;const snap=msg=>frames.push({kind:'rows',rows:[{label:'词项 A · postings',values:[...a],hot:[i]},{label:'词项 B · postings',values:[...b],hot:[j]},{label:'AND · 交集结果',values:[...out]}],msg,metrics:{'i / j':`${i} / ${j}`,'已检索共同文档':out.length}});snap('双指针从两表开头开始。');while(i<a.length&&j<b.length){if(a[i]===b[j]){out.push(a[i]);snap(`docID=${a[i]} 相等，输出并同时推进。`);i++;j++}else if(a[i]<b[j]){snap(`${a[i]}<${b[j]}，A 当前值不可能再匹配，推进 i。`);i++}else{snap(`${a[i]}>${b[j]}，推进 j。`);j++}}snap(`一条表耗尽，查询结束，结果 [${out.join(', ')}]。`);return frames}
export function queensTrace(n){assert(Number.isInteger(n)&&n>=1&&n<=8,'请输入 1–8 的棋盘边长。');let queens=[],frames=[],visited=0;const snap=(msg,attempt=null,bad=false)=>frames.push({kind:'board',n,queens:[...queens],attempt,bad,msg,metrics:{'已放皇后':queens.length,'尝试位置数':visited}});snap('逐行、逐列尝试；遇到冲突立即剪枝。');function dfs(r){if(r===n){snap('找到一个完整解。列坐标（从 1 开始）：'+queens.map(c=>c+1).join(', '));return true}for(let c=0;c<n;c++){visited++;const bad=queens.some((q,i)=>q===c||Math.abs(q-c)===r-i);snap(`尝试第 ${r+1} 行、第 ${c+1} 列：${bad?'冲突，剪枝':'合法，可继续'}。`,[r,c],bad);if(!bad){queens.push(c);snap('放置皇后，递归下一行。');if(dfs(r+1))return true;queens.pop();snap('此分支无解，撤销当前行皇后。')}}return false}if(!dfs(0))snap(`${n} 皇后没有可行解，全部候选已检查。`);return frames}
export function turnpikeTrace(distances){assert(distances.every(v=>v>0),'距离必须为正整数。');const n=(1+Math.sqrt(1+8*distances.length))/2;assert(Number.isInteger(n)&&n>=2&&n<=7,'距离数量必须为 n(n−1)/2，且点数 2–7。');let remaining=sorted(distances),L=remaining.pop(),points=[0,L],frames=[],visits=0;const snap=msg=>frames.push({kind:'rows',rows:[{label:'已放坐标',values:sorted(points)},{label:'剩余距离多重集',values:[...remaining]}],msg,metrics:{'目标点数':n,'总长度 L':L}});snap(`固定端点 0 与 ${L}，移除一个最大距离。`);function dfs(){assert(++visits<=20000,'该实例搜索过多，请用较小距离集合。');if(!remaining.length)return points.length===n;const d=remaining.at(-1);for(const x of [...new Set([d,L-d])]){if(x<=0||x>=L||points.includes(x))continue;const need=points.map(p=>Math.abs(p-x)),copy=[...remaining];let valid=true;for(const v of need){const i=copy.indexOf(v);if(i===-1){valid=false;break}copy.splice(i,1)}snap(`尝试坐标 ${x}，需要距离 [${need.join(', ')}]：${valid?'多重集包含':'缺少必要距离，剪枝'}。`);if(valid){const old=remaining;remaining=copy;points.push(x);snap(`放置 ${x} 并扣除距离。`);if(dfs())return true;points.pop();remaining=old;snap(`撤销 ${x}，恢复全部距离重数。`)}}return false}const found=dfs();snap(found?'重构成功。反射后的坐标也可能构成一个解。':'遍历所有可行候选后无解。');return frames}
export function minimaxTrace(values){const d=Math.log2(values.length);assert(Number.isInteger(d)&&d>=1&&d<=4,'请输入 2、4、8 或 16 个叶值。');let id=0;function build(a,depth){const t={v:id++,label:'?',meta:depth%2?'MIN':'MAX',children:[]};if(a.length===1){t.value=a[0];t.label=String(a[0]);t.meta='leaf';return t}t.children=[build(a.slice(0,a.length/2),depth+1),build(a.slice(a.length/2),depth+1)];return t}const root=build(values,0),frames=[];let visited=0;const snap=(msg,hot=[])=>frames.push({kind:'tree',roots:[clone(root)],hot,msg,metrics:{'访问叶数':visited,'全部叶数':values.length}});const fmt=x=>Number.isFinite(x)?x:x>0?'∞':'−∞';function mark(t){t.meta='pruned';t.children.forEach(mark)}function search(t,depth,a,b){if(!t.children.length){visited++;snap(`访问叶值 ${t.value}。`,[t.v]);return t.value}let value=depth%2?Infinity:-Infinity;for(let i=0;i<t.children.length;i++){const v=search(t.children[i],depth+1,a,b);value=depth%2?Math.min(value,v):Math.max(value,v);if(depth%2)b=Math.min(b,value);else a=Math.max(a,value);t.label=String(value);snap(`${depth%2?'MIN':'MAX'} 更新，α=${fmt(a)}，β=${fmt(b)}。`,[t.v]);if(a>=b&&i<t.children.length-1){t.children.slice(i+1).forEach(mark);t.label=(depth%2?'≤':'≥')+value;snap('α ≥ β，剩余兄弟不能改善祖先选择，剪枝。',[t.v]);break}}return value}snap('根为 MAX，各层 MAX / MIN 交替，从左到右访问。');const result=search(root,0,-Infinity,Infinity);root.label=String(result);snap(`根的 Minimax 精确值 = ${result}。`);return frames}
export function mergeTrace(values){const a=[...values],frames=[];const snap=(msg,hot=[])=>frames.push({kind:'array',array:[...a],hot,msg,metrics:{'元素数':a.length,'算法':'稳定归并'}});snap('输入数组。');function sort(l,r){if(r-l<=1)return;const m=(l+r)>>1;snap(`分解区间 [${l},${r})，中点 ${m}。`,Array.from({length:r-l},(_,i)=>l+i));sort(l,m);sort(m,r);const left=a.slice(l,m),right=a.slice(m,r),out=[];let i=0,j=0;while(i<left.length||j<right.length){if(j===right.length||(i<left.length&&left[i]<=right[j]))out.push(left[i++]);else out.push(right[j++])}a.splice(l,r-l,...out);snap(`归并 [${l},${m}) 与 [${m},${r})，相等取左边。`,Array.from({length:r-l},(_,i)=>l+i))}sort(0,a.length);snap('所有区间归并完成。');return frames}
function pointsParser(raw,max=16){const p=raw.split(/[;；]/).map(s=>ints(s,2));assert(p.length>=2&&p.length<=max&&p.every(p=>p.length===2),`输入 2–${max} 个 x,y 点，用分号隔开。`);return p.map(([x,y],i)=>({x,y,id:i}))}
const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
export function closestTrace(points){const f=[],px=[...points].sort((a,b)=>a.x-b.x||a.y-b.y),py=[...points].sort((a,b)=>a.y-b.y||a.x-b.x);let best=Infinity,pair=[],compares=0;const snap=(msg,hot=[],line)=>f.push({kind:'points',points,hot,pair:[...pair],line,msg,metrics:{'当前最小距离':Number.isFinite(best)?best.toFixed(4):'∞','比较次数':compares}});function cmp(a,b){compares++;const d=distance(a,b);if(d<best){best=d;pair=[a.id,b.id]}snap(`比较点 ${a.id+1} 与 ${b.id+1}，距离 ${d.toFixed(4)}。`,[a.id,b.id]);return d}snap('先按 x 与 y 分别排序；点编号保持输入顺序。');function rec(x,y){if(x.length<=3){let d=Infinity;for(let i=0;i<x.length;i++)for(let j=i+1;j<x.length;j++)d=Math.min(d,cmp(x[i],x[j]));return d}const m=x.length>>1,l=x.slice(0,m),r=x.slice(m),ids=new Set(l.map(p=>p.id)),mid=(l.at(-1).x+r[0].x)/2;snap(`沿 x=${mid} 划分 ${x.length} 个点。`,x.map(p=>p.id),mid);const dl=rec(l,y.filter(p=>ids.has(p.id))),dr=rec(r,y.filter(p=>!ids.has(p.id)));let d=Math.min(dl,dr);const strip=y.filter(p=>Math.abs(p.x-mid)<d);snap('合并：仅检查条带内按 y 排序的候选。',strip.map(p=>p.id),mid);for(let i=0;i<strip.length;i++)for(let j=i+1;j<strip.length&&j<=i+7&&strip[j].y-strip[i].y<d;j++)d=Math.min(d,cmp(strip[i],strip[j]));return d}for(let i=1;i<px.length;i++)if(px[i].x===px[i-1].x&&px[i].y===px[i-1].y){cmp(px[i],px[i-1]);snap('存在重复坐标，最近距离为 0。');return f}rec(px,py);snap(`最近点对 ${pair.map(i=>i+1).join('、')}，距离 ${best.toFixed(4)}。`);return f}
export function matrixTrace(p){assert(p.length>=3&&p.length<=9&&p.every(x=>x>0),'请输入 3–9 个正整数维度（表示 2–8 个矩阵）。');const n=p.length-1,m=Array.from({length:n},()=>Array(n).fill(null)),s=Array.from({length:n},()=>Array(n).fill(null)),f=[];for(let i=0;i<n;i++)m[i][i]=0;const snap=(msg,hot=[])=>f.push({kind:'matrix',matrix:clone(m),hot,labels:Array.from({length:n},(_,i)=>'A'+(i+1)),msg,metrics:{'矩阵个数':n,'当前 m[1,n]':m[0][n-1]??'尚未计算'}});snap('对角线为 0：单个矩阵不需要乘法。');for(let len=2;len<=n;len++)for(let i=0;i+len<=n;i++){const j=i+len-1;for(let k=i;k<j;k++){const val=m[i][k]+m[k+1][j]+p[i]*p[k+1]*p[j+1];if(m[i][j]===null||val<m[i][j]){m[i][j]=val;s[i][j]=k}snap(`区间 A${i+1}…A${j+1}，切在 A${k+1} 后：${m[i][k]} + ${m[k+1][j]} + ${p[i]}×${p[k+1]}×${p[j+1]} = ${val}，保留最小 ${m[i][j]}。`,[[i,j],[i,k],[k+1,j]])}}function plan(i,j){if(i===j)return'A'+(i+1);const k=s[i][j];return'('+plan(i,k)+'·'+plan(k+1,j)+')'}snap(`最优次数 ${m[0][n-1]}。括号化：${plan(0,n-1)}。`,[[0,n-1]]);return f}
function graphParser(raw){const sections=raw.split('|');assert(sections.length===2,'格式：顶点数 | 起点,终点,权重; ...（顶点从 0 开始）');const n=Number(sections[0]);assert(Number.isInteger(n)&&n>=2&&n<=7,'顶点数需为 2–7。');const edges=sections[1].split(/[;；]/).filter(s=>s.trim()).map(s=>ints(s,3));assert(edges.length&&edges.length<=25&&edges.every(e=>e.length===3&&e[0]>=0&&e[0]<n&&e[1]>=0&&e[1]<n&&e[0]!==e[1]),'边格式为 u,v,w，端点在 0…n−1，且不同。最多 25 条。');return{n,edges}}
export function floydTrace({n,edges}){const d=Array.from({length:n},(_,i)=>Array.from({length:n},(_,j)=>i===j?0:Infinity)),f=[];for(const[u,v,w]of edges)d[u][v]=Math.min(d[u][v],w);const snap=(msg,hot=[])=>f.push({kind:'matrix',matrix:clone(d),hot,msg,metrics:{'图类型':'有向图','允许负边':'是；检查负环'}});snap('初始化为直接边权，无边记 ∞，对角线 0。');for(let k=0;k<n;k++){snap(`允许顶点 ${k} 成为中间点。`);for(let i=0;i<n;i++)for(let j=0;j<n;j++)if(d[i][k]+d[k][j]<d[i][j]){const old=d[i][j];d[i][j]=d[i][k]+d[k][j];snap(`借助 ${k} 更新 ${i}→${j}：${old===Infinity?'∞':old} → ${d[i][j]}。`,[[i,j],[i,k],[k,j]])}}const negative=[];for(let i=0;i<n;i++)if(d[i][i]<0)negative.push(i);if(negative.length){for(let i=0;i<n;i++)for(let j=0;j<n;j++)if(negative.some(k=>d[i][k]<Infinity&&d[k][j]<Infinity))d[i][j]=-Infinity;snap('检测到负环；能经过负环的点对标为 −∞，不存在有限最短路。',negative.map(i=>[i,i]))}else snap('全部中间点处理完成；无负环，矩阵给出所有点对最短距离。');return f}
function knapsackParse(raw){const a=raw.split('|');assert(a.length===2,'格式：容量 | 重量,价值; 重量,价值');const W=Number(a[0]);assert(Number.isInteger(W)&&W>=1&&W<=25,'容量需为 1–25 的整数。');const items=a[1].split(/[;；]/).map(s=>positive(s,2));assert(items.length<=8&&items.every(a=>a.length===2),'请输入至多 8 件物品，每件重量和价值均为正整数。');return{W,items}}
export function knapsackTrace({W,items}){const n=items.length,d=Array.from({length:n+1},()=>Array(W+1).fill(0)),f=[];const snap=(msg,hot=[])=>f.push({kind:'matrix',matrix:clone(d),hot,msg,metrics:{'容量':W,'物品数':n,'当前最优值':d[n][W]}});snap('第 0 行与容量 0 的值为 0。');for(let i=1;i<=n;i++){const[w,v]=items[i-1];for(let c=1;c<=W;c++){d[i][c]=d[i-1][c];if(c>=w)d[i][c]=Math.max(d[i][c],d[i-1][c-w]+v);snap(`物品 ${i}（重 ${w}，价值 ${v}），容量 ${c}：${c<w?'不能装入':'比较不取与取一次'}，dp=${d[i][c]}。`,[[i,c],[i-1,c],...(c>=w?[[i-1,c-w]]:[])])}}let c=W,chosen=[];for(let i=n;i>0;i--)if(d[i][c]!==d[i-1][c]){chosen.push(i);c-=items[i-1][0]}snap(`最优价值 ${d[n][W]}，选择物品编号 [${chosen.reverse().join(', ')}]。`,[[n,W]]);return f}
function activityParse(raw){const a=raw.split(/[;；]/).map(s=>ints(s,2));assert(a.length<=16&&a.every(x=>x.length===2&&x[0]<x[1]),'输入至多 16 个 start,end 活动，用分号分隔，且 start < end。');return a.map(([s,e],i)=>({s,e,id:i}))}
export function activityTrace(items){const order=[...items].sort((a,b)=>a.e-b.e||a.id-b.id),chosen=[],rejected=[],f=[];let last=-Infinity;const snap=(msg,active)=>f.push({kind:'intervals',items,chosen:[...chosen],rejected:[...rejected],active,msg,metrics:{'已选择活动数':chosen.length,'上一结束时刻':last===-Infinity?'−∞':last}});snap('按结束时间排序：'+order.map(i=>i.id+1).join(', '));for(const x of order){if(x.s>=last){chosen.push(x.id);last=x.e;snap(`接受活动 ${x.id+1} [${x.s},${x.e})，它与已选活动兼容。`,x.id)}else{rejected.push(x.id);snap(`跳过活动 ${x.id+1}，开始 ${x.s} < 上次结束 ${last}。`,x.id)}}snap(`结束，最多兼容活动数为 ${chosen.length}。`);return f}
export function huffmanTrace(values){assert(values.every(v=>v>0),'符号频率必须为正整数。');assert(values.length<=12,'最多 12 个符号。');let id=0,queue=values.map((v,i)=>({v:id++,weight:v,label:v,meta:String.fromCharCode(65+i),symbol:String.fromCharCode(65+i),children:[]})),f=[],cost=0;const snap=(msg,hot=[])=>f.push({kind:'tree',roots:clone(queue),hot,msg,metrics:{'当前合并成本和':cost,'剩余树数':queue.length}});snap('每个符号成为一棵树，标注频率。');while(queue.length>1){queue.sort((a,b)=>a.weight-b.weight||a.v-b.v);const a=queue.shift(),b=queue.shift(),p={v:id++,weight:a.weight+b.weight,label:a.weight+b.weight,children:[a,b]};cost+=p.weight;queue.push(p);snap(`合并两个最小频率 ${a.weight} 与 ${b.weight}，产生权重 ${p.weight}。`,[p.v,a.v,b.v])}const codes=[];function walk(t,path){if(t.symbol)codes.push(t.symbol+': '+(path||'0'));else t.children.forEach((c,i)=>walk(c,path+i))}walk(queue[0],'');snap(values.length===1?`单符号约定码 0；理论树 WPL=0，实际约定编码位数=${values[0]}。`:`最优 WPL=${cost}；左 0 右 1，码表 ${codes.join('，')}。`);return f}
function reductionParse(raw){const parts=raw.split('|'),n=Number(parts[0]);assert(parts.length===2&&Number.isInteger(n)&&n>=3&&n<=7,'格式：3–7 的顶点数 | u,v;u,v；顶点从 0 开始。');const edges=parts[1].trim()?parts[1].split(/[;；]/).map(s=>ints(s,2)):[];assert(edges.every(e=>e.length===2&&e[0]>=0&&e[0]<n&&e[1]>=0&&e[1]<n&&e[0]!==e[1]),'边必须为范围内的两个不同顶点。');return{n,edges}}
export function reductionTrace({n,edges}){const original=new Set(edges.map(([a,b])=>[Math.min(a,b),Math.max(a,b)].join(','))),weighted=[];for(let u=0;u<n;u++)for(let v=u+1;v<n;v++)weighted.push([u,v,original.has(`${u},${v}`)?1:2]);const f=[{kind:'graph',n,edges:edges.map(([a,b])=>[a,b,1]),msg:'原图：判断是否存在经过所有顶点恰一次的 Hamilton 圈。',metrics:{'顶点数 n':n}},{kind:'graph',n,edges:weighted,msg:'构造完全图：原边权 1，缺失边权 2，阈值 K=n。虚线表示补出的权 2 边。',metrics:{'TSP 判定阈值':n,'构造成本':'O(n²)'}}];let best=Infinity,tour=[];function dfs(path,rest,cost){if(!rest.length){const end=path.at(-1),total=cost+(original.has([0,end].sort((a,b)=>a-b).join(','))?1:2);if(total<best){best=total;tour=[...path,0]}return}for(const v of rest){const last=path.at(-1),w=original.has([last,v].sort((a,b)=>a-b).join(','))?1:2;dfs([...path,v],rest.filter(x=>x!==v),cost+w)}}dfs([0],Array.from({length:n-1},(_,i)=>i+1),0);f.push({kind:'graph',n,edges:weighted,tour,msg:`小规模穷举验证：最短巡回 ${tour.join('→')}，代价 ${best}。${best<=n?'TSP 为 yes，原图存在 Hamilton 圈。':'TSP 为 no，原图不存在 Hamilton 圈。'}穷举仅为演示核对，并非归约步骤。`,metrics:{'最优巡回成本':best,'阈值 K':n}});return f}
function binParse(raw){const parts=raw.split('|'),strategy=parts.length===2?parts[0].trim().toUpperCase():'NF',a=(parts.at(-1)).split(/[,，\s]+/).filter(Boolean);assert(['NF','FF','FFD'].includes(strategy),'策略为 NF、FF 或 FFD。');assert(a.length>=1&&a.length<=16&&a.every(t=>/^\d*(?:\.\d{1,3})?$/.test(t)&&Number(t)>0&&Number(t)<=1),'输入 1–16 个 (0,1] 的物品，最多 3 位小数。');return{strategy,items:a.map(s=>Math.round(Number(s)*1000))}}
export function exactBins(items){const a=sorted(items).reverse();let best=a.length,loads=[];function go(i){if(loads.length>=best)return;if(i===a.length){best=loads.length;return}let seen=new Set();for(let j=0;j<loads.length;j++)if(!seen.has(loads[j])&&loads[j]+a[i]<=1000){seen.add(loads[j]);loads[j]+=a[i];go(i+1);loads[j]-=a[i]}loads.push(a[i]);go(i+1);loads.pop()}go(0);return best}
export function binTrace({strategy,items}){const a=strategy==='FFD'?sorted(items).reverse():[...items],bins=[],f=[],lower=Math.ceil(a.reduce((s,x)=>s+x,0)/1000),opt=a.length<=12?exactBins(a):null;const snap=(msg)=>f.push({kind:'bins',bins:clone(bins),msg,metrics:{'策略':strategy,'已用箱数':bins.length,'体积下界':lower,'穷举 OPT（≤12 件）':opt??'本例未计算'}});snap(`物品处理顺序 [${a.map(v=>v/1000).join(', ')}]。`);for(const x of a){let k=-1;if(strategy==='NF'){if(bins.length&&bins.at(-1).reduce((s,v)=>s+v,0)+x<=1000)k=bins.length-1}else k=bins.findIndex(b=>b.reduce((s,v)=>s+v,0)+x<=1000);if(k<0){k=bins.length;bins.push([])}bins[k].push(x);snap(`将 ${x/1000} 放入第 ${k+1} 箱，载荷 ${bins[k].reduce((s,v)=>s+v,0)/1000}。`)}snap(`完成，用 ${bins.length} 箱。${opt!==null?`本例精确 ALG/OPT=${(bins.length/opt).toFixed(3)}；不是普适近似保证。`:'OPT 未计算，体积下界不能替代 OPT。'}`);return f}
function centerParse(raw){const a=raw.split('|');assert(a.length===2,'格式：k | x,y; x,y; ...');const points=pointsParser(a[1],14),k=Number(a[0]);assert(Number.isInteger(k)&&k>=1&&k<=points.length,'k 需为 1 到点数之间的整数。');return{k,points}}
export function centerTrace({k,points}){const centers=[],f=[];let radius=Infinity;const snap=msg=>{const assignments=points.map(p=>centers.reduce((best,c)=>best===undefined||distance(p,points[c])<distance(p,points[best])?c:best,undefined));radius=centers.length?Math.max(...points.map((p,i)=>distance(p,points[assignments[i]]))):Infinity;f.push({kind:'points',points,centers:[...centers],assignments,msg,metrics:{'已选中心 / k':`${centers.length} / ${k}`,'覆盖半径':Number.isFinite(radius)?radius.toFixed(4):'∞'}})};snap('以输入的第一个点为初始中心。');centers.push(0);snap('选择中心 1。');while(centers.length<k){let far=-1,dist=-1;points.forEach((p,i)=>{if(centers.includes(i))return;const d=Math.min(...centers.map(c=>distance(p,points[c])));if(d>dist){dist=d;far=i}});centers.push(far);snap(`选择距现有中心最远的点 ${far+1}，原距离 ${dist.toFixed(4)}。`)}snap(`得到 ${k} 个中心。覆盖半径 ${radius.toFixed(4)}，满足度量模型下 R≤2OPT。`);return f}
export function maxcutTrace({n,edges}){assert(edges.every(e=>e[2]>0),'Max-Cut 演示要求正整数边权。');const side=Array(n).fill(0),f=[];const value=s=>edges.reduce((v,[a,b,w])=>v+(s[a]!==s[b]?w:0),0);let opt=0;for(let mask=0;mask<(1<<n);mask++){const s=Array.from({length:n},(_,i)=>(mask>>i)&1);opt=Math.max(opt,value(s))}const snap=(msg,hot=[])=>f.push({kind:'graph',n,edges,side:[...side],hot,msg,metrics:{'当前割权':value(side),'穷举全局最优':opt,'当前值 / OPT':(value(side)/opt).toFixed(3)}});snap('从所有顶点同侧开始，每次选择收益最大的正收益翻转。');while(true){let gain=0,u=-1;for(let i=0;i<n;i++){let g=0;for(const[a,b,w]of edges)if(a===i||b===i)g+=(side[a]===side[b]?w:-w);if(g>gain){gain=g;u=i}}if(u<0)break;side[u]^=1;snap(`翻转顶点 ${u}，割权增加 ${gain}。`,[u])}snap(`无正收益翻转，达到单翻转局部最优。割权 ${value(side)}，全局最优 ${opt}。`);return f}
function seedParse(raw){const p=raw.split('|');assert(p.length===2,'格式：随机种子 | 整数序列');const seed=Number(p[0]);assert(Number.isInteger(seed)&&seed>=0&&seed<=4294967295,'种子为 0–4294967295 的整数。');return{seed,values:ints(p[1],24)}}
function rng(seed){return()=>{seed=(Math.imul(1664525,seed)+1013904223)>>>0;return seed/4294967296}}
export function quickTrace({seed,values}){const a=[...values],rand=rng(seed),f=[];let comp=0;const snap=(msg,hot=[])=>f.push({kind:'array',array:[...a],hot,msg,metrics:{'随机种子':seed,'三路分类次数':comp}});snap('固定输入，使用指定种子产生可复现的枢轴序列。');function sort(l,r){if(r-l<=1)return;const pi=l+Math.floor(rand()*(r-l)),pivot=a[pi];snap(`在 [${l},${r}) 随机选枢轴 ${pivot}。`,[pi]);let lt=l,i=l,gt=r;while(i<gt){comp++;if(a[i]<pivot){[a[i],a[lt]]=[a[lt],a[i]];lt++;i++}else if(a[i]>pivot){gt--;[a[i],a[gt]]=[a[gt],a[i]]}else i++;snap(`三路划分：小于区 [${l},${lt})，等于区 [${lt},${i})，待判定 [${i},${gt})。`,Array.from({length:Math.max(0,i-lt)},(_,j)=>lt+j))}sort(l,lt);sort(gt,r)}sort(0,a.length);snap('排序完成。一次轨迹的成本不能替代期望分析。');return f}
export function hiringTrace({seed,values}){assert(new Set(values).size===values.length,'雇佣实验需要互不相同的资格分数。');const a=[...values],random=rng(seed);for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}let best=-Infinity,hires=0,f=[],H=values.reduce((s,_,i)=>s+1/(i+1),0);const snap=(msg,i)=>f.push({kind:'array',array:[...a],hot:i===undefined?[]:[i],msg,metrics:{'累计雇佣':hires,'理论 E[H]':H.toFixed(4),'种子':seed}});snap('Fisher–Yates 洗牌后的面试顺序。分数越高越好。');for(let i=0;i<a.length;i++){if(a[i]>best){best=a[i];hires++;snap(`第 ${i+1} 位分数 ${a[i]}，超过此前最好，雇佣。`,i)}else snap(`第 ${i+1} 位分数 ${a[i]}，不超过 ${best}，不雇佣。`,i)}snap(`完成，本次雇佣 ${hires} 人。理论期望 ${H.toFixed(4)} 是对均匀随机排列的期望。`);return f}
export function sumTrace(values){const original=values.length,n=2**Math.ceil(Math.log2(original));let rows=[{label:'输入（补零到二次幂）',values:[...values,...Array(n-original).fill(0)]}],f=[],work=0;const snap=msg=>f.push({kind:'rows',rows:clone(rows),msg,metrics:{'加法工作量':work,'完成归约层数':rows.length-1}});snap('同一层的加法相互独立，下一层等待本层完成。');while(rows.at(-1).values.length>1){const a=rows.at(-1).values,b=[];for(let i=0;i<a.length;i+=2){b.push(a[i]+a[i+1]);work++}rows.push({label:`归约层 ${rows.length}`,values:b});snap(`本层执行 ${b.length} 次并行加法。`)}snap(`结果 ${rows.at(-1).values[0]}，加法总数 ${work}。`);return f}
export function prefixTrace(values){const original=values.length,n=2**Math.ceil(Math.log2(original)),a=[...values,...Array(n-original).fill(0)],f=[];let work=0;const snap=(msg,hot=[])=>f.push({kind:'rows',rows:[{label:'原输入',values:[...values]},{label:'工作数组（必要时末尾补零）',values:[...a],hot}],msg,metrics:{'已执行加法':work,'原始元素数':original}});snap('上扫：每段的和存到该段末尾。');for(let width=2;width<=n;width*=2){const hot=[];for(let r=width-1;r<n;r+=width){a[r]+=a[r-width/2];work++;hot.push(r)}snap(`上扫宽度 ${width}，同层各段独立相加。`,hot)}a[n-1]=0;snap('把整树根的前缀设为 0，开始下扫。',[n-1]);for(let width=n;width>=2;width/=2){const hot=[];for(let r=width-1;r<n;r+=width){const l=r-width/2,t=a[l];a[l]=a[r];a[r]=a[r]+t;work++;hot.push(l,r)}snap(`下扫宽度 ${width}：左继承 prefix，右为 prefix+左区间和。`,hot)}snap(`exclusive 结果 [${a.slice(0,original).join(', ')}]；inclusive 为 [${a.slice(0,original).map((v,i)=>v+values[i]).join(', ')}]。`);return f}
function externalParse(raw){const s=raw.split('|');assert(s.length===2,'格式：内存容量M,归并路数k | 整数序列');const p=positive(s[0],2);assert(p.length===2&&p[0]>=3&&p[0]<=12&&p[1]>=2&&p[1]<=p[0]-1,'演示设 B=1，M 为 3–12，k 为 2…M−1。');return{M:p[0],k:p[1],values:ints(s[1],32)}}
export function externalTrace({M,k,values}){let runs=[],f=[],pass=0;const snap=msg=>f.push({kind:'rows',rows:runs.map((a,i)=>({label:'Run '+(i+1),values:[...a]})),msg,metrics:{'内存 M / 块 B':`${M} / 1`,'归并路数':k,'已完成归并轮':pass,'剩余段':runs.length}});for(let i=0;i<values.length;i+=M){runs.push(sorted(values.slice(i,i+M)));snap(`读入并内排第 ${runs.length} 块内存数据，写出初始 run。`)}while(runs.length>1){const next=[];for(let i=0;i<runs.length;i+=k){const group=runs.slice(i,i+k),p=group.map(()=>0),out=[];while(true){let j=-1;for(let z=0;z<group.length;z++)if(p[z]<group[z].length&&(j===-1||group[z][p[z]]<group[j][p[j]]))j=z;if(j===-1)break;out.push(group[j][p[j]++]);f.push({kind:'rows',rows:[...group.map((a,z)=>({label:'输入 Run '+(i+z+1),values:[...a],hot:[p[z]]})),{label:'本组合并输出',values:[...out]}],msg:`从第 ${j+1} 个输入缓冲取出最小值 ${out.at(-1)}。`,metrics:{'当前归并轮':pass+1,'本组输入段数':group.length,'教学实现':'线性扫描表头'}})}next.push(out)}runs=next;pass++;snap(`第 ${pass} 轮完成，得到 ${runs.length} 个 run。`)}snap(`外部排序完成。初始生成加 ${pass} 轮归并；图中保留全部记录便于教学，实际缓冲只需各段表头块。`);return f}
function replacementParse(raw){const a=raw.split('|'),M=Number(a[0]);assert(a.length===2&&Number.isInteger(M)&&M>=2&&M<=10,'格式：2–10 的内存容量 | 整数序列');return{M,values:ints(a[1],32)}}
export function replacementTrace({M,values}){let active=sorted(values.slice(0,M)),frozen=[],i=Math.min(M,values.length),runs=[[]],f=[];const snap=msg=>f.push({kind:'rows',rows:[{label:'活动最小堆（按值展示）',values:[...active]},{label:'冻结到下一段',values:[...frozen]},{label:'尚未读入',values:values.slice(i)},...runs.map((a,j)=>({label:'输出 Run '+(j+1),values:[...a]}))],msg,metrics:{'驻留记录数':active.length+frozen.length,'内存容量':M,'已生成段数':runs.length}});snap('读入前 M 条，构成活动最小堆。');while(active.length||frozen.length){if(!active.length){active=sorted(frozen);frozen=[];runs.push([]);snap('活动堆为空，开启新 run 并解冻。')}const x=active.shift();runs.at(-1).push(x);let message=`输出最小值 ${x}。`;if(i<values.length){const y=values[i++];if(y>=x){active=sorted([...active,y]);message+=`新值 ${y}≥${x}，留在当前 run。`}else{frozen.push(y);message+=`新值 ${y}<${x}，冻结。`}}snap(message)}snap(`完成，生成 ${runs.length} 个有序段。活动堆与冻结区总容量始终不超过 M。`);return f}
const D=(title,label,defaultValue,parse,run,code)=>({title,label,default:defaultValue,parse,run,code});
